'use strict';

const url = require('url');

/**
 * Приводит record.req к следующему формату:
 *  – {String} method        – HTTP метод из req.method
 *  – {String} url           – Полный адрес страницы, включая протокол и хост
 *  – {Object} headers       – Заголовки из req.headers
 *  – {*}      body          – Тело запроса из req.body
 *  – {String} remoteAddress – IP адрес пользователя
 *  – {String} remotePort    - Порт пользователя
 *  – {String} yandexuid     - Значение yandexuid из кук пользователя
 *
 * @returns {Function}
 */
module.exports = () => {
    /**
     * @param {Object} record
     * @returns {undefined}
     */
    return record => {
        const req = record.req;
        if (!req) {
            return;
        }

        try {
            const urlObj = url.parse(req.originalUrl || req.url || '');
            urlObj.protocol = req.protocol;
            urlObj.hostname = req.hostname;

            record.req = {
                method: req.method || 'GET',
                url: url.format(urlObj),
                headers: req.headers,
                body: req.body,
                remoteAddress: req.connection && req.connection.remoteAddress,
                remotePort: req.connection && req.connection.remotePort,
                yandexuid: req.cookies && req.cookies.yandexuid,
            };
        } catch (err) {
            record.req = '[logger: failed to parse record.req]';
        }
    };
};
